package com.hbm.client.excavator;
import com.hbm.machine.electricfurnace.FurnaceUpgradeItem;import net.minecraft.ChatFormatting;import net.minecraft.client.Minecraft;import net.minecraft.network.chat.Component;import net.neoforged.api.distmarker.Dist;import net.neoforged.bus.api.SubscribeEvent;import net.neoforged.fml.common.EventBusSubscriber;import net.neoforged.neoforge.event.entity.player.ItemTooltipEvent;
@EventBusSubscriber(modid="hbm",value=Dist.CLIENT)public final class ExcavatorUpgradeHelp {
 @SubscribeEvent public static void tooltip(ItemTooltipEvent event){if(!(Minecraft.getInstance().screen instanceof ExcavatorScreen)||!(event.getItemStack().getItem() instanceof FurnaceUpgradeItem item))return;int tier=item.tier();event.getToolTip().add(Component.translatable("tile.machine_excavator.name").withStyle(ChatFormatting.YELLOW));if(item.type()==FurnaceUpgradeItem.Type.SPEED){event.getToolTip().add(Component.translatable("upgrade.delay","-"+(100-200/(tier+2))+"%").withStyle(ChatFormatting.GREEN));event.getToolTip().add(Component.translatable("upgrade.consumption","+"+tier*100+"%").withStyle(ChatFormatting.RED));}else event.getToolTip().add(Component.translatable("upgrade.consumption","-"+(100-100/(tier+1))+"%").withStyle(ChatFormatting.GREEN));}private ExcavatorUpgradeHelp(){}
}
